import { z } from 'zod';
import scrapeCreatorsManifestJson from '../scrapecreators-manifest.json';

/**
 * scrapecreators-manifest.json is ScrapeCreators' published OpenAPI spec
 * (https://docs.scrapecreators.com/openapi.json) cut down to what this plugin
 * uses: one entry per route with its query parameters and the top-level fields
 * of its documented response. Each operation's `id` is its Corsair name
 * (`tiktok.profile`). Generated by kits/plugin-gen/scrapecreators/gen.py.
 *
 * The manifest is not run through zod at import: schema.test.ts checks the
 * file with `ScrapeCreatorsManifestSchema` instead.
 */

const ParamSchema = z
	.object({
		name: z.string().min(1),
		type: z.enum(['string', 'number', 'integer', 'boolean']),
		required: z.boolean(),
		description: z.string(),
		enum: z.array(z.string()).min(1).optional(),
		/** A pagination cursor that ScrapeCreators sometimes returns as a number. */
		acceptsNumber: z.boolean().optional(),
	})
	.strict();

const OutputFieldKind = z.enum([
	'string',
	'number',
	'boolean',
	'array',
	'object',
	'unknown',
]);

const OperationSchema = z
	.object({
		id: z.string().regex(/^[a-z][A-Za-z0-9]*\.[a-z][A-Za-z0-9]*$/),
		method: z.literal('GET'),
		path: z.string().regex(/^\/v[1-3]\/[A-Za-z0-9/-]+$/),
		/** The route also takes the same fields as a JSON POST body (for long cursors). */
		postFallback: z.boolean(),
		tag: z.string(),
		summary: z.string(),
		shortDescription: z.string().min(1),
		description: z.string(),
		params: z.array(ParamSchema),
		output: z
			.object({
				kind: z.enum(['object', 'array']),
				/** Top-level fields, or each row's fields for an `array` response. */
				fields: z.record(z.string(), OutputFieldKind),
			})
			.strict(),
	})
	.strict();

export const ScrapeCreatorsManifestSchema = z
	.object({
		source: z.string().url(),
		operations: z.array(OperationSchema),
	})
	.strict();

export type ScrapeCreatorsParamDefinition = z.infer<typeof ParamSchema>;
export type ScrapeCreatorsOutputFieldKind = z.infer<typeof OutputFieldKind>;
export type ScrapeCreatorsOperationDefinition = z.infer<typeof OperationSchema>;
type ScrapeCreatorsManifest = z.infer<typeof ScrapeCreatorsManifestSchema>;

// Typed by ScrapeCreatorsManifestSchema; schema.test.ts parses the file with it.
export const scrapeCreatorsManifest =
	// `unknown` is necessary because a JSON import's inferred type is too wide to assign directly; schema.test.ts parses the file with ScrapeCreatorsManifestSchema.
	scrapeCreatorsManifestJson as unknown as ScrapeCreatorsManifest;

export const scrapeCreatorsOperations: readonly ScrapeCreatorsOperationDefinition[] =
	scrapeCreatorsManifest.operations;
